SELECT CASE WHEN s.rating >= 4.6 THEN 'high' WHEN s.rating >= 2.3 THEN 'mid' ELSE 'low' END AS rating_bucket, MAX(ss.sale_date) AS latest_sale_date, MIN(ss.revenue) AS min_revenue FROM store_sales ss FULL OUTER JOIN products p ON ss.product_id = p.id FULL OUTER JOIN suppliers s ON p.supplier_id = s.id WHERE s.country IN ('JP', 'TH') GROUP BY CASE WHEN s.rating >= 4.6 THEN 'high' WHEN s.rating >= 2.3 THEN 'mid' ELSE 'low' END;
